+// #1394 READONLY_DIAGNOSTIC_ONLY: exact candidate vs prior baseline, on an owned DB clone.
+#[cfg(test)]
+mod readonly_reuse_pilot {
+    use super::*;
+    #[test]
+    #[ignore = "owned complete S16 DB/WAL/SHM clone only"]
+    fn readonly_audit_reuse_pilot() {
+        let path = std::env::var("S3_REUSE_PILOT_DB").expect("explicit owned DB required");
+        let output = std::env::var("S3_REUSE_PILOT_OUTPUT").expect("explicit fresh output required");
+        let mut conn = Connection::open_with_flags(&path, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();
+        conn.pragma_update(None, "query_only", true).unwrap();
+        assert_eq!(conn.query_row("PRAGMA query_only", [], |r| r.get::<_,i64>(0)).unwrap(), 1);
+        let mut reports = Vec::new();
+        let mut prior = None;
+        for repeat in 0..2 {
+            let tx = conn.transaction().unwrap();
+            crate::audit_shadow_probe::reset();
+            let started = std::time::Instant::now();
+            let (result, events, work) = traced(true, || audit(&tx));
+            let elapsed = started.elapsed().as_nanos().to_string();
+            let counters = crate::audit_shadow_probe::snapshot();
+            let audited = result.unwrap();
+            // Enumerated AuditedState members: raw, cuts, objects, auxiliary.
+            // PublishedCut fields: metadata, roots, batch_id, snapshot, delta.
+            let full = json!({"raw":audited.raw,
+                "cuts":audited.cuts.iter().map(|c| json!({"metadata":format!("{:?}",c.metadata),
+                    "roots":format!("{:?}",c.roots),"batch_id":c.batch_id,
+                    "snapshot":c.snapshot.to_transport_json(),"delta":c.delta.to_transport_json()})).collect::<Vec<_>>(),
+                "objects":format!("{:?}",audited.objects),"auxiliary":format!("{:?}",audited.auxiliary)});
+            let fingerprint = sha256_hex(canonical_json(&full).as_bytes());
+            if let Some(ref p) = prior { assert_eq!(p, &fingerprint); } else { prior=Some(fingerprint.clone()); }
+            println!("READONLY_AUDIT_REPEAT repeat={} elapsed_ns={} cuts={} raw={}",repeat,elapsed,audited.cuts.len(),audited.raw.len());
+            reports.push(json!({"repeat":repeat,"elapsed_ns":elapsed,"events":events,"work":work,
+                "counters":counters,"fingerprint_sha256":fingerprint,"full_returned_state":full}));
+            drop(audited);
+            drop(tx);
+        }
+        let report=json!({"kind":"READONLY_DIAGNOSTIC_ONLY","pid":std::process::id(),"db":path,
+            "connection":"SQLITE_OPEN_READ_ONLY + PRAGMA query_only=ON; full cloned WAL present",
+            "measurement":"state::audit only; no Driver, service, commit, checkpoint or cache configuration",
+            "profile":"release test bin, opt-level=3; cfg(test) observer overhead included",
+            "heap_peak":"UNMEASURED","rss_peak":"external sampler only",
+            "source_scope":"all found SQLite read_material reads, including repeated reads; excludes control/raw SQL",
+            "source_unique_scope":"unique digest among found SQLite reads; not business evidence or admission",
+            "repeats":reports});
+        let bytes=canonical_json(&report);
+        use std::io::Write;
+        let mut out=std::fs::OpenOptions::new().write(true).create_new(true).open(output).unwrap();
+        out.write_all(bytes.as_bytes()).unwrap(); out.sync_all().unwrap();
+    }
+}
